  ,@('nangman', '확인', '[미발행] 부동산 블로그, 답이 아니라 방법을 씁니다', '부동산 데이터 분석, 답이 아니라 방법을 씁니다')
)

$todo = @(); $log = @(); $done = 0
foreach ($p in $pairs) {
  $dir = Join-Path $root $p[0]
  $old = Join-Path $dir $p[1]
  $new = Join-Path $dir $p[2]
  if (-not (Test-Path -LiteralPath $old)) {
    if (Test-Path -LiteralPath $new) { $done++ } else { $log += ('폴더를 못 찾음(건너뜀): ' + $p[0] + ' | ' + $p[1]) }
    continue
  }
  if (Test-Path -LiteralPath $new) { $log += ('같은 이름이 이미 있음(건너뜀): ' + $p[0] + ' | ' + $p[2]); continue }
  $todo += ,$p
}
Write-Host ''
Write-Host ('바꿀 폴더 ' + $todo.Count + '개') -ForegroundColor Yellow
foreach ($p in $todo) {
  Write-Host ('  ' + $p[0] + ' | ' + $p[1])
  Write-Host ('      -> ' + $p[2]) -ForegroundColor Green
}
if ($done -gt 0) { Write-Host ('이미 바뀌어 있는 폴더 ' + $done + '개') -ForegroundColor DarkGray }
if ($log.Count -gt 0) { Write-Host ''; $log | ForEach-Object { Write-Host $_ -ForegroundColor DarkGray } }
Write-Host ''
Write-Host '이름은 그대로 두는 폴더 (직접 보고 정하세요)' -ForegroundColor Yellow
foreach ($n in $notes) {
  $path = Join-Path (Join-Path $root $n[0]) $n[2]
  if (-not (Test-Path -LiteralPath $path)) { continue }
  if ($n[1] -eq '겹침') { $why = '올라간 글의 옛 원고로 보임' } elseif ($n[1] -eq '지남') { $why = '예약 날짜가 지났는데 발행 목록에 같은 제목이 없음' } else { $why = '같은 검색어로 올라간 글이 있음' }
  Write-Host ('  ' + $n[0] + ' | ' + $n[2])
  Write-Host ('      ' + $why + ': ' + $n[3]) -ForegroundColor DarkGray
}
Write-Host ''
if ($todo.Count -eq 0) { Write-Host '바꿀 폴더가 없습니다.'; return }
$ans = Read-Host '위 목록대로 이름을 바꾸려면 Y 를 누르고 Enter (그만두려면 그냥 Enter)'
if ($ans -notmatch '^[Yy]') { Write-Host '바꾸지 않았습니다.'; return }
$ok = 0
foreach ($p in $todo) {
  $old = Join-Path (Join-Path $root $p[0]) $p[1]
  try {
    Rename-Item -LiteralPath $old -NewName $p[2] -ErrorAction Stop
    $ok++; $log += ('바꿈: ' + $p[0] + ' | ' + $p[1] + ' -> ' + $p[2])
  } catch {
    $log += ('실패: ' + $p[0] + ' | ' + $p[1] + ' | ' + $_.Exception.Message)
    Write-Host ('실패: ' + $p[1] + ' | ' + $_.Exception.Message) -ForegroundColor Red
  }
}
$log += ('모두 ' + $ok + '개 바꿈 / 대상 ' + $todo.Count + '개')
$out = Join-Path $root '폴더이름_결과.txt'
[IO.File]::WriteAllLines($out, [string[]]$log, (New-Object Text.UTF8Encoding $true))
Write-Host ''
Write-Host ('모두 ' + $ok + '개 바꿨습니다. 기록: ' + $out) -ForegroundColor Yellow
